/**
 * The `$id` stamped into lib/settings.schema.json: the raw copy at HEAD, naming no release. Editors pin a version
 * through the same URL at a release ref (see the README), and a versioned $id would need the schema regenerated on
 * every major bump's release PR.
 */
export const SCHEMA_ID =
  "https://raw.githubusercontent.com/Vivswan/github-settings-as-code/HEAD/lib/settings.schema.json";
